import React from 'react';
import logo from './logo.svg';
import './App.css';
import { Route, Routes } from 'react-router-dom';
import CheckIn from './Pages/Checkin';
import Profile from './Pages/Profile';
import Layout from './Layout/Layout';
import Home from './Pages/Home';
import ProfileCard from './Pages/Profile';
import NurseWorkForm from './Pages/Nurse/NurseWorkForm';
import CarLoan from './Pages/Car';
import { Login } from '@mui/icons-material';
import LoginPage from './Pages/Login/Login';
import { UserProvider } from './Context/userContext';
import SupplyHome from './Pages/Supply';
import NurseList from './Pages/Nurse/NurseList';
import TopBar from './Component/TopBar';
import { InventoryTransactionProvider } from './Context/InventoryTransactionContext';
import { ThemeProvider } from '@emotion/react';
import theme from './theme';
const token = localStorage.getItem('token');
function App() {
  return (

    <ThemeProvider theme={theme}>
      <div className="App">
        <TopBar />
        <div style={{ marginTop: 65 }}>
          {token ? (<UserProvider><Layout ><Routes>
            <Route path="/" element={<Home />}></Route>
            <Route path="nurse" element={<NurseList />}></Route>
            <Route path="ot" element={<NurseList />}></Route>
            <Route path="nurse/form" element={<NurseWorkForm />}></Route>
            <Route path="checkin" element={<CheckIn />}></Route>
            <Route path="supply" element={<InventoryTransactionProvider><SupplyHome /></InventoryTransactionProvider>}></Route>
            <Route path="profile" element={<ProfileCard />}></Route>
            <Route path="work" element={<ProfileCard />}></Route>
            <Route path='car' element={<CarLoan />}></Route>
          </Routes></Layout></UserProvider>) : (<Routes><Route path='*' element={<LoginPage />}></Route></Routes>)}
        </div>
      </div>
    </ThemeProvider>
  );
}

export default App;
